"""
wpp_letterhead_assets.py — ERA cover-letter letterhead assets, base64-embedded.
Mirrors the VTI_B64 pattern (no container asset path). Both pre-trimmed to ink.
    ERA_LOGO_B64 : full-color ERA logo (orange arc + navy wordmark) on white.
    VTI_B64      : Value Through Insight mark (blue).
Use:  from wpp_letterhead_assets import era_logo_uri, vti_uri
      ctx["era_logo_uri"] = era_logo_uri()
      ctx["vti_uri"]      = vti_uri()
"""
ERA_LOGO_B64 = ""
VTI_B64 = ""

def era_logo_uri() -> str: return "data:image/png;base64," + ERA_LOGO_B64
def vti_uri() -> str:      return "data:image/png;base64," + VTI_B64
